sys_script_include.script:
var CountCIClass = Class.create();
CountCIClass.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getCount: function() {
		var ci_id = this.getParameter('ci');

		if(ci_id != '')  {
			var ciRecord = new GlideRecord('cmdb_ci');
			//gets the class name
			var className = ciRecord.getRecordClassName();

			// to get the count directly instead of GlideRecord
			var ga = new GlideAggregate('cmdb_ci');
			ga.addQuery('sys_class_name', className);
			ga.addAggregate('COUNT');
			ga.query();

			if (ga.next()) {
				return ga.getAggregate('COUNT');
			}
		}
	},
    type: 'CountCIClass'
});
